/* Shared pure data helpers. This file contains no personal bookmarks. */
(function(root,factory){const api=factory();if(typeof module==='object'&&module.exports)module.exports=api;else root.BookmarkCore=api;})(typeof globalThis!=='undefined'?globalThis:this,()=>{
  const decode=s=>String(s||'').replace(/&#(x[\da-f]+|\d+);|&(amp|lt|gt|quot|apos|nbsp);/gi,(m,num,name)=>{if(num){const n=num[0].toLowerCase()==='x'?parseInt(num.slice(1),16):Number(num);return n>0&&n<=0x10ffff?String.fromCodePoint(n):'';}return {amp:'&',lt:'<',gt:'>',quot:'"',apos:"'",nbsp:' '}[name.toLowerCase()];});
  function safeUrl(value){try{const u=new URL(value);return ['http:','https:'].includes(u.protocol)&&!u.username&&!u.password?u.href:null;}catch{return null;}}
  function normalize(entries){if(!Array.isArray(entries))throw new Error('收藏夹格式不正确');return entries.slice(0,30000).flatMap((b,i)=>{const url=safeUrl(b.url);if(!url)return [];const folder=Array.isArray(b.folder)?b.folder.map(String):[String(b.folder||'未分类')];const added=Number(b.added)||0;return [{id:String(i),title:String(b.title||b.name||new URL(url).hostname).slice(0,500),url,domain:new URL(url).hostname,folder,added,description:String(b.description||'').slice(0,2000)}];});}
  function fromEdge(data){if(!data?.roots)throw new Error('这不是 Edge 收藏夹文件');const result=[];const labels={bookmark_bar:'收藏夹栏',other:'其他收藏夹',synced:'移动收藏夹'};function walk(node,folder){if(node.type==='url'){let added=0;try{added=Number(BigInt(node.date_added||'0')/1000n)-11644473600000;}catch{}result.push({title:node.name,url:node.url,folder,added:Math.max(0,added)});}else for(const child of node.children||[])walk(child,child.type==='folder'?[...folder,child.name||'未命名文件夹']:folder);}for(const [key,node]of Object.entries(data.roots))walk(node,[labels[key]||node.name||key]);return normalize(result);}
  function fromHtml(text){if(!/<A\b/i.test(text))throw new Error('文件中没有收藏链接');const result=[],stack=[];let pending='';const tokens=/<H3\b[^>]*>([\s\S]*?)<\/H3\s*>|<DL\b[^>]*>|<\/DL\s*>|<A\b([^>]*)>([\s\S]*?)<\/A\s*>/gi;for(const m of text.matchAll(tokens)){if(m[1]!==undefined)pending=decode(m[1].replace(/<[^>]*>/g,''));else if(/^<DL/i.test(m[0])){stack.push(pending);pending='';}else if(/^<\/DL/i.test(m[0]))stack.pop();else {const attrs={};for(const a of m[2].matchAll(/([\w-]+)\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s>]+))/g))attrs[a[1].toLowerCase()]=decode(a[2]??a[3]??a[4]);result.push({title:decode(m[3].replace(/<[^>]*>/g,'')),url:attrs.href,folder:stack.filter(Boolean),added:Number(attrs.add_date||0)*1000});}}return normalize(result);}
  function siteKey(value){const host=new URL(value).hostname.toLowerCase();if(/(^|\.)youtube\.com$/.test(host)||host==='youtu.be')return 'youtube.com';return host.replace(/^(www\d*|m|mobile)\./,'');}
  function folderTree(items,paths=[]){const roots=[],map=new Map();function add(path){let siblings=roots;for(let depth=0;depth<path.length;depth++){const partial=path.slice(0,depth+1),key=JSON.stringify(partial);let node=map.get(key);if(!node){node={key,path:partial,name:path[depth],count:0,children:[]};map.set(key,node);siblings.push(node);}siblings=node.children;}return map.get(JSON.stringify(path));}for(const path of paths)if(Array.isArray(path)&&path.length)add(path);for(const b of items){if(!b.folder.length){let node=map.get('[]');if(!node){node={key:'[]',path:[],name:'未分类',count:0,children:[]};map.set('[]',node);roots.push(node);}node.count++;continue;}add(b.folder);for(let depth=1;depth<=b.folder.length;depth++)map.get(JSON.stringify(b.folder.slice(0,depth))).count++;}return {roots,nodes:[...map.values()]};}
  function edgeFolders(data){const paths=[];function walk(node,path){paths.push(path);for(const child of node.children||[])if(child.type==='folder')walk(child,[...path,child.name||'未命名文件夹']);}const labels={bookmark_bar:'收藏夹栏',other:'其他收藏夹',synced:'移动收藏夹'};for(const [key,node]of Object.entries(data.roots||{}))walk(node,[labels[key]||node.name||key]);return paths;}
  function htmlFolders(text){const paths=[],stack=[];let pending='';for(const m of text.matchAll(/<H3\b[^>]*>([\s\S]*?)<\/H3\s*>|<DL\b[^>]*>|<\/DL\s*>/gi)){if(m[1]!==undefined)pending=decode(m[1].replace(/<[^>]*>/g,''));else if(/^<DL/i.test(m[0])){stack.push(pending);if(pending)paths.push(stack.filter(Boolean));pending='';}else stack.pop();}return paths;}
  function select(items,{query='',folder='',domain='',sort='source',uniqueSites=false}={}){let path=null;if(Array.isArray(folder))path=folder;else if(folder.startsWith('[')){try{const decoded=JSON.parse(folder);if(Array.isArray(decoded))path=decoded;}catch{}}function inFolder(b){if(!folder)return true;if(path)return path.length?path.every((segment,i)=>b.folder[i]===segment):b.folder.length===0;return b.folder.join('/').startsWith(folder+'/')||b.folder.join('/')===folder;}const terms=query.trim().toLocaleLowerCase().split(/\s+/).filter(Boolean);let result=items.filter(b=>terms.every(t=>`${b.title} ${b.url} ${b.folder.join('/')} ${b.description}`.toLocaleLowerCase().includes(t))&&inFolder(b)&&(!domain||siteKey(b.url)===domain));if(sort==='title')result.sort((a,b)=>a.title.localeCompare(b.title));if(sort==='domain')result.sort((a,b)=>siteKey(a.url).localeCompare(siteKey(b.url))||a.title.localeCompare(b.title));if(sort==='recent')result.sort((a,b)=>b.added-a.added);if(uniqueSites){const seen=new Set();result=result.filter(b=>{const key=siteKey(b.url);if(seen.has(key))return false;seen.add(key);return true;});}return result;}
  return {safeUrl,normalize,fromEdge,fromHtml,select,decode,siteKey,folderTree,edgeFolders,htmlFolders};
});
